def hreflang(th_path):
    p = CANON[th_path]
    base = 'https://thongwaihomestay.com'
    return (f'<link rel="alternate" hreflang="th" href="{base}{p}">\n'
            f'<link rel="alternate" hreflang="lo" href="{base}/lo{p}">\n'
            f'<link rel="alternate" hreflang="en" href="{base}/en{p}">\n'
            f'<link rel="alternate" hreflang="x-default" href="{base}{p}">')

def lang_pills(cur, th_path):
    p = CANON[th_path]
    th = f'<a href="{p}">ไทย</a>' if cur != 'th' else '<span class="on">ไทย</span>'
    lo = f'<a href="/lo{p}">ລາວ</a>' if cur != 'lo' else '<span class="on">ລາວ</span>'
    en = f'<a href="/en{p}">EN</a>' if cur != 'en' else '<span class="on">EN</span>'
    return th + lo + en

def rewrite_links(h, lang):
    # ย้ายลิงก์ภายในไปโซนภาษา (asset/รูป/tel/https ไม่แตะ)
    def repl(m):
        url = m.group(2)
        if url.startswith(('/images', '/assets', '/videos', '/api', 'http', 'tel:', 'mailto:', '#')):
            return m.group(0)
        if url == '/':
            return f'{m.group(1)}"/{lang}/"'
        if url.startswith('/#'):
            return f'{m.group(1)}"/{lang}/{url[1:]}"'
        if url.startswith('/availability') or url.startswith('/rooms'):
            return f'{m.group(1)}"/{lang}{url}"'
        return m.group(0)
    return re.sub(r'(href=)"([^"]+)"', repl, h)

def build(th_path, lang, D):
    h = open(th_path, encoding='utf-8').read()
    # ตัด comment ไทย (โน้ตนักพัฒนา — หน้าแปลเป็นไฟล์ generate)
    h = re.sub(r'<!--[^>]*?[ก-๙].*?-->', '', h, flags=re.S)
    h = re.sub(r'(^|[ \t])//[^\n]*[ก-๙][^\n]*', r'\1', h, flags=re.M)
    h = re.sub(r'/\*[^*]*[ก-๙].*?\*/', '', h, flags=re.S)
    # แทนที่ยาว→สั้น กันคำซ้อน
    hits = 0
    for k in sorted(D, key=len, reverse=True):
        if k in h:
            h = h.replace(k, D[k]); hits += 1
    # locale + lang + og + canonical + hreflang
    h = h.replace("'th-TH'", f"'{LOCALE[lang]}'")
    h = h.replace('<html lang="th">', f'<html lang="{lang}">')
    h = h.replace('content="th_TH"', f'content="{OG[lang]}"')
    p = CANON[th_path]
    h = h.replace(f'https://thongwaihomestay.com{p}"', f'https://thongwaihomestay.com/{lang}{p}"')
    h = re.sub(r'(<link rel="canonical"[^>]*>)', r'\1\n' + hreflang(th_path), h)
    # ลิงก์ภายในก่อน แล้วค่อยฝังปุ่มภาษา (กันปุ่มไทยโดน rewrite ทับ)
    h = rewrite_links(h, lang)
    # ลิงก์ใน JS literals (การ์ดปฏิทิน + ป้ายการ์ดหน้าแรก) — รูรั่วที่ทำให้ภาษาไม่ติดตาม
    for js_path in ("'/availability/'", "'/rooms/jaosua1/'", "'/rooms/jaosua2/'", "'/rooms/tent/'"):
        h = h.replace(js_path, f"'/{lang}" + js_path[1:])
    h = re.sub(r'<div class="langs">.*?</div>', '<div class="langs">' + lang_pills(lang, th_path) + '</div>', h, flags=re.S)
    h = re.sub(r'<div class="mnav-langs">.*?</div>', '<div class="mnav-langs">' + lang_pills(lang, th_path) + '</div>', h, flags=re.S)
    # NAME_MAP ในหน้า availability
    if 'availability' in th_path:
        nm = ', '.join(f"{k}:'{v}'" for k, v in NAME_MAP[lang].items())
        h = h.replace('const ROOM_IMG = {', f'const NAME_MAP = {{ {nm} }};\n  const ROOM_IMG = {{')
        h = h.replace('${r.name}', '${NAME_MAP[r.id]||r.name}')
    return h, hits

def thai_residue(h):
    # อนุญาตเฉพาะ pill "ไทย" (ลิงก์สลับภาษา) และสัญลักษณ์ ฿ (สกุลเงิน)
    out = []
    for t in re.findall(r'[ก-๙]+', h):
        t = t.replace('฿', '')
        if t and t != 'ไทย': out.append(t)
    return out

if __name__ == '__main__':
    total_res = 0
    for th_path, (en_path, lo_path) in PAGES.items():
        for lang, out, D in (('en', en_path, EN), ('lo', lo_path, LO)):
            html, hits = build(th_path, lang, D)
            res = thai_residue(html)
            os.makedirs(os.path.dirname(out) or '.', exist_ok=True)
            open(out, 'w', encoding='utf-8').write(html)
            print(f'{out}: {hits} replacements, residue={len(res)}' + (f' ⚠ {sorted(set(res))[:8]}' if res else ' ✓'))
            total_res += len(res)
    sys.exit(1 if total_res else 0)
